<?php require __DIR__ . '/footer.php'; require __DIR__ . '/connect.php'; require __DIR__ . '/mailer.php'; $sent=false; if($_SERVER['REQUEST_METHOD']==='POST'){ $email=filter_input(INPUT_POST,'email',FILTER_VALIDATE_EMAIL); if($email){$token=bin2hex(random_bytes(16)); $expires=date('Y-m-d H:i:s',time()+3600); $stmt=$mysqli->prepare('UPDATE users SET reset_token=?, reset_expires=? WHERE email=?'); $stmt->bind_param('sss',$token,$expires,$email); $stmt->execute(); send_exam_mail($email,'Reset password','http://localhost/CISC3003-FinalExam-Paper02C/reset_password.php?token='.$token); $sent=true;}} ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Forgot Password</title><link rel="stylesheet" href="../css/styles.css"></head><body><header><h1>C.07 Password Reset by Email</h1><nav><a href="login.php">Login</a></nav></header><main><section class="card"><?php if($sent):?><div class="notice success">Reset link sent or written to debug log.</div><?php endif;?><form method="post"><label>Email</label><input name="email" type="email" required><button>Send Reset Link</button></form></section></main><?php exam_footer(); ?></body></html>
